#include "portfolio.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
static double ms(clock_t a,clock_t b){return 1000.0*(double)(b-a)/CLOCKS_PER_SEC;}
static int sorted(const Asset*a,int n){for(int i=1;i<n;i++)if(strcmp(a[i-1].symbol,a[i].symbol)>0)return 0;return 1;}
static void fill(Asset*a,int n,int kind){for(int i=0;i<n;i++){int key=kind==0?n-i:(kind==1?i:(i%7));snprintf(a[i].symbol,MAX_NAME,"S%07d",key);a[i].price=100+i%10000;a[i].return_score=1+i%30;a[i].risk=1+i%10;a[i].sector=i%10;a[i].transaction_limit=1;}}
static void bench_sort(FILE*f,const char*name,int n,int kind){Asset*a=malloc((size_t)n*sizeof(*a)),*b=malloc((size_t)n*sizeof(*b));if(!a||!b){free(a);free(b);return;}fill(a,n,kind);memcpy(b,a,(size_t)n*sizeof(*a));clock_t s=clock();merge_sort_assets(a,n);clock_t e=clock();fprintf(f,"sorting,Merge Sort,%s,%d,%.6f,%zu,%s,%s\n",name,n,ms(s,e),(size_t)2*n*sizeof(Asset),sorted(a,n)?"exact":"ERROR",sorted(a,n)?"sorted":"failed");s=clock();quick_sort_assets(b,n);e=clock();fprintf(f,"sorting,Quick Sort,%s,%d,%.6f,%zu,%s,%s\n",name,n,ms(s,e),(size_t)n*sizeof(Asset),sorted(b,n)?"exact":"ERROR",sorted(b,n)?"sorted":"failed");free(a);free(b);}
static void bench_portfolio(FILE*f,const Asset*a,int n,const char*scenario,int budget,int risk){clock_t s,e;Portfolio p;s=clock();p=portfolio_greedy(a,n,budget,risk);e=clock();fprintf(f,"portfolio,Greedy Heuristic,%s,%d,%.6f,%zu,heuristic,%d\n",scenario,n,ms(s,e),(size_t)n*sizeof(int),p.return_score);s=clock();p=portfolio_dp(a,n,budget,risk);e=clock();fprintf(f,"portfolio,Dynamic Programming,%s,%d,%.6f,%zu,exact,%d\n",scenario,n,ms(s,e),(size_t)(n+1)*(budget+1)*(risk+1)*sizeof(int),p.return_score);}
int main(void){FILE*f=fopen("output/benchmark_results.csv","w");Asset a[MAX_ASSETS];int n;if(!f){fprintf(stderr,"Cannot open output/benchmark_results.csv\n");return 1;}fprintf(f,"category,algorithm,scenario,input_size,time_ms,space_bytes,quality,objective\n");bench_sort(f,"small-reverse",100,0);bench_sort(f,"medium-reverse",1000,0);bench_sort(f,"large-reverse",10000,0);bench_sort(f,"stress-reverse",50000,0);bench_sort(f,"adversarial-many-duplicates",50000,2);n=load_assets_csv("data/assets.csv",a,MAX_ASSETS);if(n>0&&validate_assets(a,n)){bench_portfolio(f,a,n,"normal",10000,20);bench_portfolio(f,a,n,"constraint-shock",5000,10);}fclose(f);printf("Wrote output/benchmark_results.csv\n");return 0;}
